use model::*;
use std::collections::{BTreeMap,BTreeSet};
#[derive(Clone,Copy,PartialEq)]enum Destination{Body,Skip,Fonts,Colors,Picture}
#[derive(Clone)]struct State{dest:Destination,first:bool,star:bool,uc:usize,codepage:u16,font:i32,character:CharacterProperties,paragraph:ParagraphProperties}
