    fn finish_table(&mut self){if let Some(t)=self.table.take(){self.doc.sections[0].blocks.push(Block::Table(t));}}
    fn paragraph(&mut self,force:bool)->Result<(),String>{self.flush()?;if !force&&self.paragraph.content.is_empty(){return Ok(());}if self.paragraph.content.is_empty(){self.paragraph.properties=self.state.paragraph.clone();}let mut next=Paragraph::plain("");next.style=None;next.content.clear();let p=std::mem::replace(&mut self.paragraph,next);if let Some(row)=&mut self.row{row.content.push(Block::Paragraph(p));}else{self.finish_table();self.doc.sections[0].blocks.push(Block::Paragraph(p));}if self.doc.sections[0].blocks.len()>100000{return Err("Too many RTF blocks".into());}Ok(())}
