    fn row(&mut self)->Result<(),String>{if !self.paragraph.content.is_empty()||!self.text.is_empty()||!self.ansi.is_empty()||self.row.as_ref().is_some_and(|r|!r.content.is_empty()){self.cell()?;}let row=self.row.take().ok_or("RTF row terminator outside a table")?;if row.cells.is_empty(){return Err("Empty RTF row".into());}if !row.edges.is_empty()&&row.edges.len()!=row.cells.len(){return Err("RTF row definitions do not match cell count".into());}let table=self.table.get_or_insert_with(||Table{id:NodeId::new(),properties:Default::default(),rows:Vec::new()});if table.rows.len()>=10000{return Err("Too many RTF rows".into());}if table.rows.is_empty(){let mut prev=0;table.properties.grid_column_widths_mm=row.edges.iter().map(|e|{let w=(*e-prev)as f32*25.4/1440.0;prev=*e;w}).collect();}table.rows.push(TableRow{id:NodeId::new(),cells:row.cells,repeat_as_header:false,allow_break_across_pages:true,height_mm:None});Ok(())}
